const $=id=>document.getElementById(id);
const json=async(url,options={})=>{
  const controller=new AbortController();
  const timeoutMs=Number(options.timeoutMs??8000);
  const timer=setTimeout(()=>controller.abort(),Math.max(1000,timeoutMs));
  const {timeoutMs:_timeoutMs,...fetchOptions}=options;
  try{
    const r=await fetch(url,{headers:{'content-type':'application/json',...(fetchOptions.headers||{})},...fetchOptions,signal:controller.signal});
    const body=await r.json().catch(()=>({}));
    if(!r.ok)throw new Error(body.error||r.statusText||`HTTP ${r.status}`);
    return body;
  }catch(e){
    if(e?.name==='AbortError')throw new Error(`Request timed out: ${url}`);
    throw e;
  }finally{clearTimeout(timer)}
};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={};let config={};let toolsState=null;let projectState=null;let projectListState=[];let planState=[];let lastHealthAt=null;let lastGoodState=null;let deepHealthPromise=null;let healthRetryTimer=null;let fastFailureStreak=0;let deepFailureStreak=0;let livenessFailureStreak=0;let lastFastSuccessAt=null;let lastLivenessAt=null;let healthMeta={status:'warming',source:'none',fastLatencyMs:null,deepLatencyMs:null,livenessLatencyMs:null,snapshotAgeMs:null,collectedAt:null,collectorLatencyMs:null,usingLastKnownGood:false,lastError:null};
function toast(message){const el=$('toast');if(!el)return;el.textContent=message;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',3500)}
function metric(value,label){return `<div class="metric"><strong>${esc(value)}</strong><span>${esc(label)}</span></div>`}
function relativeTime(input){if(!input)return'—';const t=new Date(input).getTime();if(!Number.isFinite(t))return esc(input);const sec=Math.max(0,Math.round((Date.now()-t)/1000));if(sec<60)return`${sec}s trước`;if(sec<3600)return`${Math.round(sec/60)} phút trước`;if(sec<86400)return`${Math.round(sec/3600)} giờ trước`;return new Date(t).toLocaleString('vi-VN')}
function uptimeLabel(ms){const s=Math.max(0,Math.floor(Number(ms)||0)/1000);if(s<60)return`${Math.round(s)}s`;if(s<3600)return`${Math.floor(s/60)}m`;if(s<86400)return`${Math.floor(s/3600)}h ${Math.floor((s%3600)/60)}m`;return`${Math.floor(s/86400)}d ${Math.floor((s%86400)/3600)}h`}
function setText(id,value){const el=$(id);if(el)el.textContent=value}
function gotoTab(id){const button=document.querySelector(`nav button[data-tab="${id}"]`);if(!button)return;document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x===button));document.querySelectorAll('.tab').forEach(tab=>tab.classList.toggle('active',tab.id===id));if(id==='activity')loadActivity();if(id==='automation')loadRuns();if(id==='skills'){loadSkills();loadTools()}if(id==='desktop')loadScreens();if(id==='projects')loadProject();if(id==='chat-health'&&window.loadChatHealth)window.loadChatHealth();window.scrollTo({top:0,behavior:'smooth'})}
