async function timedJson(url,options={}){const started=performance.now();const data=await json(url,options);return{data,latencyMs:Math.max(0,performance.now()-started)}}
function healthAgeLabel(ms){if(ms==null||!Number.isFinite(Number(ms)))return'age —';const n=Math.max(0,Number(ms));return n<1000?`age ${Math.round(n)} ms`:`age ${(n/1000).toFixed(n<10000?1:0)} s`}
