function applyFastSnapshot(result){const fast=result?.data;if(!fast||!fast.available||!fast.data)return false;state=fast.data;lastGoodState=state;fastFailureStreak=0;deepFailureStreak=0;livenessFailureStreak=0;lastFastSuccessAt=Date.now();if(healthRetryTimer){clearTimeout(healthRetryTimer);healthRetryTimer=null}healthMeta={status:fast.state||'healthy',source:'fast',fastLatencyMs:result.latencyMs,deepLatencyMs:null,livenessLatencyMs:null,snapshotAgeMs:fast.ageMs,collectedAt:fast.collectedAt,collectorLatencyMs:fast.collectorLatencyMs?.last??null,usingLastKnownGood:fast.state==='stale',lastError:fast.lastError||fast.deepHealthReason||null};return true}
