async function probeLiveness(timeoutMs=4000){try{const live=await timedJson('/api/health/live',{timeoutMs});livenessFailureStreak=0;lastLivenessAt=Date.now();healthMeta={...healthMeta,livenessLatencyMs:live.latencyMs};if(!lastGoodState&&live.data?.ok){state={...state,version:live.data.version,instanceId:live.data.instanceId,port:live.data.port};}return{ok:true,result:live}}catch(error){livenessFailureStreak+=1;healthMeta={...healthMeta,livenessLatencyMs:null};return{ok:false,error}}}
