function markColdStartFailure(error){fastFailureStreak+=1;const message=error?.message||String(error||'Fast Health check failed');healthMeta={...healthMeta,status:'revalidating',source:'none',fastLatencyMs:null,deepLatencyMs:null,usingLastKnownGood:false,lastError:`Health startup check ${fastFailureStreak} is still warming/revalidating. ${message}`};return healthMeta.status}
function markFastFailure(error){fastFailureStreak+=1;const message=error?.message||String(error||'Fast Health check failed');const status=fastFailureStreak===1?'revalidating':fastFailureStreak<4?'degraded':'reconnecting';healthMeta={...healthMeta,status,source:'last-known-good',fastLatencyMs:null,deepLatencyMs:null,usingLastKnownGood:true,lastError:fastFailureStreak===1?`Fast Health missed 1 check; revalidating without declaring MCP offline. ${message}`:`Fast Health missed ${fastFailureStreak} consecutive checks. ${message}`};return status}
async function refreshDeepHealth(reason='fallback',timeoutMs=12000){if(deepHealthPromise)return deepHealthPromise;deepHealthPromise=(async()=>{try{const deep=await timedJson('/api/health',{timeoutMs});state=deep.data;lastGoodState=state;deepFailureStreak=0;const fastIssue=reason==='fast-fallback'&&fastFailureStreak>0;healthMeta={...healthMeta,status:fastIssue?'degraded':'healthy',source:'deep',deepLatencyMs:deep.latencyMs,snapshotAgeMs:0,collectedAt:new Date().toISOString(),usingLastKnownGood:false,lastError:fastIssue?`Fast Health missed ${fastFailureStreak} consecutive check${fastFailureStreak===1?'':'s'}; deep health confirms MCP is online.`:null};lastHealthAt=new Date();renderCore();return true}catch(e){deepFailureStreak+=1;if(lastGoodState){state=lastGoodState;const liveOk=recentlyLive();const unavailable=!liveOk&&fastFailureStreak>=5&&deepFailureStreak>=2&&livenessFailureStreak>=2;healthMeta={...healthMeta,status:unavailable?'unavailable':liveOk?'degraded':'reconnecting',source:liveOk?'live+last-known-good':'last-known-good',deepLatencyMs:null,usingLastKnownGood:true,lastError:liveOk?`Fast/Deep readiness checks are degraded, but MCP liveness is confirmed. ${e.message}`:`Fast + Deep + Liveness checks failed (${fastFailureStreak}/${deepFailureStreak}/${livenessFailureStreak} streak). ${e.message}`};lastHealthAt=new Date();renderCore();return false}throw e}finally{deepHealthPromise=null}})();return deepHealthPromise}
function renderUnavailable(error){healthMeta={...healthMeta,status:'unavailable',source:'none',usingLastKnownGood:false,lastError:error?.message||String(error||'Health unavailable')};setText('serviceLine',healthMeta.lastError);setText('topMcpStatus','MCP unavailable');setText('overallStatus','Connection problem');setText('backendStatus','Unavailable');const topDot=document.querySelector('.top-status .status-dot');if(topDot)topDot.className='status-dot bad';const overallDot=document.querySelector('.overall-health .status-dot');if(overallDot)overallDot.className='status-dot bad'}

let loadPromise=null;let refreshQueued=false;
async function performLoad(options={}){try{
  const [fastResult,cfgResult,toolResult]=await Promise.allSettled([timedJson('/api/health/fast',{timeoutMs:2500}),json('/api/config',{timeoutMs:4000}),json('/api/tools',{timeoutMs:4000})]);
  if(cfgResult.status==='fulfilled')config=cfgResult.value;
  if(toolResult.status==='fulfilled')toolsState=toolResult.value;
  let fast=null;let haveHealth=false;
  if(fastResult.status==='fulfilled'){fast=fastResult.value.data;haveHealth=applyFastSnapshot(fastResult.value)}
  if(!haveHealth&&lastGoodState){state=lastGoodState;markFastFailure(fastResult.status==='rejected'?fastResult.reason:new Error('Fast Health snapshot is warming or unavailable.'));haveHealth=true}
  if(!haveHealth){
    const fastError=fastResult.status==='rejected'?fastResult.reason:new Error('Fast Health snapshot is warming or unavailable.');
    markColdStartFailure(fastError);lastHealthAt=new Date();renderCore();
    if(fastFailureStreak<2){scheduleHealthRetry(900);return}
    const live=await probeLiveness(4000);
    if(live.ok){healthMeta={...healthMeta,status:'degraded',source:'live',usingLastKnownGood:false,lastError:`Fast Health is warming/degraded, but MCP liveness is confirmed.`};lastHealthAt=new Date();renderCore();scheduleHealthRetry(1200);void refreshDeepHealth('fast-fallback',12000).catch(()=>{});return}
    try{const deep=await timedJson('/api/health',{timeoutMs:15000});state=deep.data;lastGoodState=state;fastFailureStreak=0;deepFailureStreak=0;healthMeta={status:'healthy',source:'deep',fastLatencyMs:null,deepLatencyMs:deep.latencyMs,livenessLatencyMs:null,snapshotAgeMs:0,collectedAt:new Date().toISOString(),collectorLatencyMs:null,usingLastKnownGood:false,lastError:null};haveHealth=true}
    catch(deepError){deepFailureStreak+=1;const unavailable=fastFailureStreak>=5&&deepFailureStreak>=2&&livenessFailureStreak>=2;if(unavailable){renderUnavailable(deepError);return}healthMeta={...healthMeta,status:'revalidating',source:'none',usingLastKnownGood:false,lastError:`Startup Fast + Deep + Liveness checks are still revalidating (${fastFailureStreak}/${deepFailureStreak}/${livenessFailureStreak}); retrying without declaring MCP offline. ${deepError.message}`};lastHealthAt=new Date();renderCore();scheduleHealthRetry(1200);return}
  }
  lastHealthAt=new Date();renderCore();
  await Promise.all([loadProject(),loadRecentActivity(),window.loadChatHealth?window.loadChatHealth(false):Promise.resolve()]);
  const fastNeedsDeep=fast?.deepHealthRequired===true||(!fast&&fastFailureStreak>=2);
  const needsDeep=options.forceDeep||fastNeedsDeep;
  if(!options.forceDeep&&!fast&&fastFailureStreak>=2){const live=await probeLiveness(4000);if(live.ok&&lastGoodState){state=lastGoodState;healthMeta={...healthMeta,status:'degraded',source:'live+last-known-good',usingLastKnownGood:true,lastError:`Fast Health missed ${fastFailureStreak} consecutive checks; MCP liveness endpoint confirms the core is online.`};lastHealthAt=new Date();renderCore()}}
  if(needsDeep){const pending=refreshDeepHealth(options.forceDeep?'manual':'fast-fallback',options.forceDeep?15000:12000);if(options.forceDeep)await pending;else void pending.catch(()=>{})}
}catch(e){if(lastGoodState){state=lastGoodState;markFastFailure(e);lastHealthAt=new Date();renderCore();if(fastFailureStreak>=2)void refreshDeepHealth('fast-fallback',10000).catch(()=>{})}else{markColdStartFailure(e);lastHealthAt=new Date();renderCore();if(fastFailureStreak>=5&&deepFailureStreak>=2&&livenessFailureStreak>=2)renderUnavailable(e);else scheduleHealthRetry(1200)}}}
function load(options={}){
  if(loadPromise){refreshQueued=true;return loadPromise}
  loadPromise=performLoad(options).finally(()=>{loadPromise=null;if(refreshQueued){refreshQueued=false;setTimeout(()=>load(),0)}});
  return loadPromise;
}
