function renderResultTelemetry(){if(!$('resultTelemetryMetrics'))return;const t=state.resultTelemetry||{};const calls=Number(t.calls||0),p50=Number(t.p50ResultChars||0),p95=Number(t.p95ResultChars||0),large=Number(t.largeResults||0),veryLarge=Number(t.veryLargeResults||0);$('resultTelemetryMetrics').innerHTML=[metric(calls,'Recent calls'),metric(p50.toLocaleString('vi-VN'),'p50 chars'),metric(p95.toLocaleString('vi-VN'),'p95 chars'),metric(large,'> 8K'),metric(veryLarge,'> 16K')].join('');setText('resultTelemetryBadge',t.available?(veryLarge?'VERY LARGE':large?'WATCH':'HEALTHY'):'Unavailable');const badge=$('resultTelemetryBadge');if(badge)badge.className='badge '+(veryLarge?'bad':large?'warn':t.available?'ok':'neutral');const rows=Array.isArray(t.topPayloads)?t.topPayloads:[];if($('resultTelemetryBody'))$('resultTelemetryBody').innerHTML=rows.length?rows.map(x=>`<tr><td><strong>${esc(x.toolName)}</strong>${x.truncated?' · truncated':''}${x.paginated?' · paginated':''}</td><td>${Number(x.resultChars||0).toLocaleString('vi-VN')}${x.sizeCapped?' +':''}</td><td>${Number(x.estimatedTokens||0).toLocaleString('vi-VN')}</td><td>${Number(x.elapsedMs||0).toFixed(1)} ms</td><td><span class="mini-status ${x.warning==='normal'?'ok':x.warning==='very_large'?'bad':'warn'}">${esc(x.warning||'normal')}</span></td></tr>`).join(''):'<tr><td colspan="5">Chưa có tool call trong cửa sổ telemetry.</td></tr>'}
function renderAutomation(){if(!$('automationMetrics'))return;$('automationMetrics').innerHTML=[metric(state.tasks?.active||0,'Active tasks'),metric(state.tasks?.paused||0,'Paused tasks'),metric(state.terminalEnabled?'Ready':'Locked','PowerShell'),metric(state.browser?.executable?'Available':'Unavailable','Browser'),metric(state.index?.pendingActions||0,'Pending approvals'),metric(state.emergencyStop?'ON':'Off','Emergency Stop')].join('')}
function renderMemory(){if(!$('memoryMetrics'))return;const ctx=state.context||{};$('memoryMetrics').innerHTML=[metric(ctx.projects||0,'Projects'),metric(ctx.checkpoints||0,'Checkpoints'),metric(projectState?.unresolved||0,'Unresolved'),metric(projectState?.documents||0,'Documents'),metric(projectState?.decisions?.length||0,'Decisions')].join('');setText('memoryBadge',ctx.available?'Healthy':'Unavailable');if($('memoryHealth'))$('memoryHealth').innerHTML=`<div><strong>Active project root</strong><div class="project-path">${esc(ctx.activeProjectRoot||'Chưa có project active')}</div></div><div><strong>Checkpoint policy</strong><p>Memory được giữ dưới dạng metadata có giới hạn, không phải transcript đầy đủ.</p></div><div><strong>Resume strategy</strong><p>Project + checkpoint + decisions + unresolved items được ưu tiên khi chuyển chat.</p></div>`}
function dailyProgressDateLabel(value){if(!value)return'—';const m=String(value).match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?m[3]+'/'+m[2]+'/'+m[1]:String(value)}
function renderDailyProgress(data){
  const card=$('dailyProgressCard'),body=$('dailyProgressBody');if(!card||!body)return;
  const project=data?.project?.name||projectState?.name||'Project hiện tại';setText('dailyProgressProject',project);
  const badge=$('dailyProgressStatus');
  if(!data?.available||!data?.plan){if(badge){badge.className='daily-progress-status not-started';badge.innerHTML='<i></i> Chưa có kế hoạch ngày'}body.className='daily-progress-empty';body.innerHTML='<strong>Project này chưa có Daily Plan cho hôm nay.</strong><span>Khi ChatGPT/MCP tạo kế hoạch ngày, tiến độ sẽ xuất hiện ở đây và tự cập nhật theo project memory.</span>';return}
  const p=Math.max(0,Math.min(100,Number(data.percent)||0));const complete=!!data.complete;const status=data.status==='not_started'?'Chưa bắt đầu':complete?'Đã hoàn thành hôm nay':'Chưa hoàn thành hôm nay';
  if(badge){badge.className='daily-progress-status '+(complete?'complete':data.status==='not_started'?'not-started':'in-progress');badge.innerHTML='<i></i> '+esc(status)}
  const items=(data.plan.items||[]).map(item=>{const raw=Number(item.target)>0?(Number(item.current)/Number(item.target))*100:0;const pct=Math.max(0,Math.min(100,raw));const done=Number(item.current)>=Number(item.target);return '<div class="daily-progress-item '+(done?'done':'')+'"><div class="daily-progress-item-head"><strong>'+(done?'✓ ':'○ ')+esc(item.label)+'</strong><span>'+esc(item.current)+' / '+esc(item.target)+' '+esc(item.unit||'mục')+'</span></div><div class="daily-progress-track"><i style="width:'+pct+'%"></i></div></div>'}).join('');
  const remaining=complete?'Không còn đầu việc hôm nay':'Còn '+data.remainingItems+' / '+data.totalItems+' hạng mục chưa đạt mục tiêu';
  const note=data.plan.note?'<p class="daily-progress-note">'+esc(data.plan.note)+'</p>':'';const updated=data.updatedAt?' · '+relativeTime(data.updatedAt):'';
  body.className='daily-progress-layout';body.innerHTML='<div class="daily-progress-ring" style="--progress:'+p+'"><div><strong>'+p+'%</strong><span>hoàn thành</span></div></div><div class="daily-progress-content"><div class="daily-progress-title-row"><div><small>'+esc(dailyProgressDateLabel(data.date))+'</small><h3>'+esc(data.plan.title)+'</h3></div><strong class="daily-progress-remaining">'+esc(remaining)+'</strong></div><div class="daily-progress-items">'+items+'</div>'+note+'<p class="daily-progress-source">Cập nhật từ MCP project memory'+esc(updated)+'</p></div>';
}
async function loadDailyProgress(root){if(!root)return;try{const date=new Date();const key=date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0');let data=await json('/api/projects/daily-progress?root='+encodeURIComponent(root)+'&date='+key,{timeoutMs:6000});if(!data?.available){const candidates=(projectListState||[]).slice(0,12);for(const project of candidates){if(!project?.root||String(project.root).toLowerCase()===String(root).toLowerCase())continue;try{const candidate=await json('/api/projects/daily-progress?root='+encodeURIComponent(project.root)+'&date='+key,{timeoutMs:3500});if(candidate?.available){data={...candidate,trackingFallback:true};break}}catch{}}}renderDailyProgress(data)}catch(e){const body=$('dailyProgressBody');if(body){body.className='daily-progress-empty';body.innerHTML='<strong>Không đọc được tiến độ hôm nay.</strong><span>'+esc(e.message)+'</span>'}}}

function planLabel(state){return({planned:'Chưa bắt đầu',pending:'Chờ',running:'Đang chạy',paused:'Tạm dừng',blocked:'Bị chặn',verified:'Đã xác minh',completed:'Hoàn thành',failed:'Thất bại',skipped:'Bỏ qua',cancelled:'Đã hủy'})[state]||state||'—'}
function phaseMark(phase){if(phase.state==='verified')return'✓';if(phase.state==='running')return'▶';if(phase.state==='blocked')return'!';if(phase.state==='failed')return'×';if(phase.state==='skipped')return'–';return'○'}
function renderPlanState(data){
  planState=Array.isArray(data?.plans)?data.plans:[];
  const active=planState.find(p=>['running','blocked','paused','planned'].includes(p.state))||planState[0]||null;
  const badge=$('planStateBadge');const body=$('planStateBody');const overview=$('planOverviewBody');const overviewBadge=$('planOverviewBadge');
  if(!active){if(badge){badge.className='badge neutral';badge.textContent='Chưa có kế hoạch'}if(body){body.className='plan-state-empty';body.innerHTML='<strong>Chưa có kế hoạch nhiều giai đoạn cho project này.</strong><p>Khi task_plan được tạo, phase hiện tại và phase tiếp theo sẽ xuất hiện tại đây.</p>'}if(overview){overview.innerHTML='<div class="plan-state-empty"><strong>Chưa có kế hoạch nhiều giai đoạn.</strong></div>'}if(overviewBadge){overviewBadge.className='badge neutral';overviewBadge.textContent='Idle'}return}
  const pct=Math.max(0,Math.min(100,Number(active.percent)||0));const current=active.currentPhase;const next=active.nextPhase;
  if(badge){badge.className='badge '+(active.state==='completed'?'ok':active.state==='blocked'||active.state==='failed'?'bad':active.state==='paused'?'warn':'');badge.textContent=planLabel(active.state)}
  if(overviewBadge){overviewBadge.className='badge '+(active.state==='completed'?'ok':active.state==='blocked'||active.state==='failed'?'bad':active.state==='paused'?'warn':'');overviewBadge.textContent=pct+'%'}
  const headline='<div class="plan-state-head"><div><small>'+esc(active.kind==='upgrade'?'UPGRADE PLAN':'MULTI-PHASE PLAN')+'</small><h3>'+esc(active.title)+'</h3><p>'+esc(active.objective||'')+'</p></div><div class="plan-percent"><strong>'+pct+'%</strong><span>'+esc(active.verifiedPhaseCount)+' / '+esc(active.requiredPhaseCount)+' phase bắt buộc</span></div></div><div class="plan-progress"><i style="width:'+pct+'%"></i></div><div class="plan-now"><div><small>PHASE HIỆN TẠI</small><strong>'+(current?esc(current.sequence+'. '+current.title):active.state==='completed'?'Đã hoàn thành':'Chưa bắt đầu')+'</strong><span>'+(current?esc(planLabel(current.state)):'—')+'</span></div><div><small>TIẾP THEO</small><strong>'+(next?esc(next.sequence+'. '+next.title):'—')+'</strong><span>'+(next?esc(next.objective||''):'Không còn phase kế tiếp')+'</span></div></div>';
  const phases='<div class="plan-phase-list">'+(active.phases||[]).map(p=>'<div class="plan-phase '+esc(p.state)+'"><span class="plan-phase-mark">'+phaseMark(p)+'</span><div><strong>'+esc(p.sequence+'. '+p.title)+'</strong><small>'+esc(planLabel(p.state))+(p.required?' · bắt buộc':' · tùy chọn')+'</small>'+(p.note?'<p>'+esc(p.note)+'</p>':'')+'</div></div>').join('')+'</div>';
  if(body){body.className='plan-state-body';body.innerHTML=headline+phases}
  if(overview){overview.innerHTML=headline+'<div class="plan-overview-foot"><span>Được lưu bền vững trong MCP · '+esc(relativeTime(active.updatedAt))+'</span><button class="link-button" data-goto="projects">Xem toàn bộ phase ›</button></div>';overview.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>gotoTab(b.dataset.goto))}
}
async function loadPlans(root){if(!root)return renderPlanState({plans:[]});try{renderPlanState(await json('/api/plans?root='+encodeURIComponent(root)+'&limit=30',{timeoutMs:4000}))}catch(e){const body=$('planStateBody');if(body)body.innerHTML='<strong>Không đọc được Plan State.</strong><p>'+esc(e.message)+'</p>'}}

async function loadProject(){
  const root=state.context?.activeProjectRoot||state.root?.[0];
  try{
    const catalog=await json('/api/projects?limit=100').catch(()=>({projects:[],projectWorkspaceRoot:config.projectWorkspaceRoot||''}));
    projectListState=Array.isArray(catalog.projects)?catalog.projects:[];
    setText('projectWorkspaceRoot',catalog.projectWorkspaceRoot?`Folder gốc: ${catalog.projectWorkspaceRoot}`:'Chưa cấu hình folder project');
    if($('projectList'))$('projectList').innerHTML=projectListState.length?projectListState.map(p=>{
      const active=p.activeTask;
      const task=active||p.lastTask;
      const badge=active?(active.state||'active'):(task?.state||'idle');
      const plan=p.activePlan||p.lastPlan;
      return `<div class="result"><div class="panel-heading"><div><strong>${esc(p.name||'Project')}</strong><div class="path">${esc(p.root||'')}</div></div><span class="mini-status ${active?'ok':''}">${esc(badge)}</span></div><p>${active?`Đang làm: ${esc(active.objective||active.id)}`:task?`<span class="muted">Task gần nhất (${esc(({completed:'đã xong',expired:'hết hạn',failed:'thất bại',cancelled:'đã hủy',paused:'tạm dừng',planned:'chưa chạy'})[task.state]||task.state||'đã dừng')}): ${esc(task.objective||task.id)}</span>`:'Chưa có task gần đây'}</p>${plan?`<p class="detail">Plan: ${esc(plan.title)} · ${esc(plan.percent)}% · ${esc(plan.state)}</p>`:''}</div>`;
    }).join(''):'<p>Chưa có Project nào.</p>';
    if(!root)return;
    projectState=await json(`/api/projects/status?root=${encodeURIComponent(root)}`);
    setText('activeProjectName',projectState.name||'Active project');
    setText('activeProjectRoot',projectState.root||root);
    setText('projectUnresolved',`${projectState.unresolved||0} unresolved`);
    setText('projectUpdated',relativeTime(projectState.updatedAt));
    setText('projectCheckpoint',`Memory ${state.context?.checkpoints||0} checkpoint${state.context?.checkpoints===1?'':'s'}`);
    if($('projectDetails'))$('projectDetails').innerHTML=`<div class="panel-heading"><div><h2>${esc(projectState.name||'Project')}</h2><p>${esc(projectState.type||'mixed')}</p></div><span class="mini-status ok">Active</span></div><div class="project-path">${esc(projectState.root||root)}</div><div class="metrics">${metric(projectState.documents||0,'Documents')}${metric(projectState.decisions?.length||0,'Decisions')}${metric(projectState.unresolved||0,'Unresolved')}${metric(projectState.currentEdit?'Active':'None','Edit session')}${metric(projectState.lastQa?'Available':'None','Latest QA')}${metric(relativeTime(projectState.updatedAt),'Updated')}</div>`;
    renderMemory();
    await Promise.all([loadDailyProgress(root),loadPlans(root)]);
  }catch(e){if($('projectDetails'))$('projectDetails').innerHTML=`<p>${esc(e.message)}</p>`}
}
async function loadRecentActivity(){try{const r=await json('/api/activity');const rows=(r.events||[]).slice(0,6);if($('recentActivity'))$('recentActivity').innerHTML=rows.length?rows.map(x=>`<div class="compact-row"><time>${new Date(x.at).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})}</time><span>${esc(x.action)}</span><span>${esc(x.status||'')}</span></div>`).join(''):'<p>Chưa có activity.</p>'}catch(e){if($('recentActivity'))$('recentActivity').textContent=e.message}}

function normalizeChatHealth(raw){if(!raw||typeof raw!=='object')return null;const score=Number(raw.score);return{score:Number.isFinite(score)?Math.max(0,Math.min(100,Math.round(score))):null,turns:raw.turns??null,inp:raw.inpMs??raw.inp??null,heap:raw.heapMb??raw.heap??null,fps:raw.fps??null,longTasks:raw.longTasksPerMin??raw.longTasks??null,duration:raw.sessionMinutes??raw.durationMin??raw.duration??null,domNodes:raw.domNodes??null,degradation:raw.degradationPct??null,updatedAt:raw.collectedAt||raw.updatedAt||null}}
async function loadChatHealth(showToast=false){let raw=null;try{raw=await json('/api/chat-health')}catch{}if(!raw){try{raw=JSON.parse(localStorage.getItem('nhd-chat-health')||'null')}catch{}}const h=normalizeChatHealth(raw);renderChatHealth(h);if(showToast)toast(h?'Đã cập nhật Chat Health':'Chưa có cảm biến ChatGPT telemetry')}
function renderChatHealth(h){const score=h?.score;const has=Number.isFinite(score);const level=!has?'neutral':score>=80?'good':score>=65?'growing':score>=50?'handoff':'critical';const label=!has?'Chưa có telemetry':score>=80?'Healthy':score>=65?'Growing':score>=50?'Handoff recommended':'Handoff now';setText('chatHealthScore',has?score:'—');setText('chatHealthState',label);setText('chatTurns',h?.turns??'—');setText('chatInp',h?.inp!=null?`${h.inp} ms`:'—');setText('chatHeap',h?.heap!=null?`${h.heap} MB`:'—');setText('chatFps',h?.fps??'—');setText('chatLongTasks',h?.longTasks!=null?`${h.longTasks}/min`:'—');setText('chatDuration',h?.duration!=null?`${h.duration}m`:'—');setText('chatSensorBadge',has?'Sensor connected':'Sensor chưa kết nối');const ring=$('chatScoreRing');if(ring){ring.className=`score-ring ${level==='neutral'?'':level}`;ring.style.setProperty('--score-angle',`${(score||0)*3.6}deg`)}const hint=!has?'Kết nối cảm biến tab ChatGPT để đo hiệu năng thực tế.':score>=80?'Có thể tiếp tục làm việc.':score>=65?'Chat bắt đầu nặng; nên chuẩn bị checkpoint.':score>=50?'Nên hoàn tất đoạn việc hiện tại và chuẩn bị chat mới.':'Nên handoff sang chat mới ngay.';setText('chatHealthHint',hint);const rec=$('chatRecommendation');if(rec){rec.className=`recommendation ${level==='growing'||level==='handoff'?'warn':level==='critical'?'bad':'neutral'}`;rec.innerHTML=`<strong>${esc(label)}</strong><p>${esc(hint)}</p>`}if($('chatHealthMetrics'))$('chatHealthMetrics').innerHTML=[metric(has?score:'—','Health score'),metric(h?.inp!=null?`${h.inp} ms`:'—','INP'),metric(h?.fps??'—','FPS'),metric(h?.heap!=null?`${h.heap} MB`:'—','JS Heap'),metric(h?.domNodes??'—','DOM nodes'),metric(h?.degradation!=null?`${h.degradation}%`:'—','Degradation')].join('');if($('chatTelemetryDetails'))$('chatTelemetryDetails').innerHTML=has?`<div><strong>Turns:</strong> ${esc(h.turns??'—')}</div><div><strong>Long tasks:</strong> ${esc(h.longTasks??'—')} / phút</div><div><strong>Session:</strong> ${esc(h.duration??'—')} phút</div><div><strong>Last telemetry:</strong> ${esc(h.updatedAt?relativeTime(h.updatedAt):'—')}</div>`:'<span>Chưa có dữ liệu từ tab ChatGPT. UI đã sẵn sàng nhận telemetry từ sensor/extension ở bước tiếp theo.</span>'}
window.addEventListener('message',event=>{if(event.source!==window||event.data?.type!=='NHD_CHAT_HEALTH')return;localStorage.setItem('nhd-chat-health',JSON.stringify({...event.data.payload,updatedAt:new Date().toISOString()}));loadChatHealth()});

function renderScreenStatus(screen){if(!$('screenStatus'))return;$('screenStatus').textContent=!screen?.enabled?'Screen Access đang bị khóa':screen.companion?`Screen Companion đã kết nối · ${screen.displayCount||0} màn hình · ${screen.windowCount||0} cửa sổ`:'Screen Companion chưa kết nối'}
function renderDesktopStatus(){if(!$('desktopStatus'))return;$('desktopStatus').textContent=!state.desktopEnabled?'Desktop Navigation đang bị khóa':state.desktop?.companion?`UI Automation đã kết nối · ${state.desktop.windowCount||0} cửa sổ`:'UI Automation Companion chưa kết nối';setText('intakeStatus',!state.intakeEnabled?'Document Intake đang bị khóa':`${state.intake?.availableRoots||0}/${state.intake?.roots?.length||0} thư mục intake khả dụng · OCR ${state.pdf?.worker?.ocr?'sẵn sàng':'chưa có engine'}`);if($('desktopMetrics'))$('desktopMetrics').innerHTML=[metric(state.desktop?.windowCount||0,'UI windows'),metric(state.intake?.availableRoots||0,'Inbox roots'),metric(state.pdf?.worker?.render?'Ready':'Unavailable','PDF render'),metric(state.pdf?.worker?.ocr?'Ready':'Unavailable','OCR'),metric(state.screen?.sourceCount||0,'Screen sources'),metric(state.screen?.displayCount||0,'Displays')].join('')}
async function loadScreens(){renderScreenStatus(state.screen);renderDesktopStatus();const tasks=[];if(state.screenEnabled)tasks.push(json('/api/screen/sources').then(r=>$('screenSources').innerHTML=r.sources.length?`<p>Có <strong>${r.sources.length}</strong> nguồn chụp (${r.sources.filter(s=>s.kind==='display'||s.kind==='screen').length} màn hình). Tên cửa sổ được ẩn.</p><details class="private-list"><summary>Hiện danh sách</summary>${r.sources.map(s=>`<div class="result"><strong>${esc(s.name)}</strong><div class="path">${esc(s.kind)}</div></div>`).join('')}</details>`:'Không phát hiện nguồn chụp.').catch(e=>$('screenSources').textContent=e.message));else $('screenSources').textContent='Screen Access đang bị khóa.';if(state.desktopEnabled)tasks.push(json('/api/desktop/windows').then(r=>$('desktopWindows').innerHTML=r.windows.length?`<p>Phát hiện <strong>${r.windows.length}</strong> cửa sổ có thể điều hướng. Tên cửa sổ được ẩn để bảo vệ riêng tư.</p><details class="private-list"><summary>Hiện tên cửa sổ</summary>${r.windows.map(w=>`<div class="result"><strong>${esc(w.title)}</strong><div class="path">${esc(w.className)}</div></div>`).join('')}</details>`:'Không phát hiện cửa sổ UI Automation.').catch(e=>$('desktopWindows').textContent=e.message));else $('desktopWindows').textContent='Desktop Navigation đang bị khóa.';if(state.intakeEnabled)tasks.push(json('/api/intake/recent').then(r=>$('intakeFiles').innerHTML=r.files.map(f=>`<div class="result"><strong>${esc(f.name)}</strong><div class="path">${esc(f.path)} · ${f.size>=1048576?(f.size/1048576).toFixed(1)+' MB':Math.max(1,Math.round(f.size/1024))+' KB'} · ${esc(new Date(f.modifiedAt).toLocaleString('vi-VN'))}</div></div>`).join('')||'Không có tài liệu mới trong inbox.').catch(e=>$('intakeFiles').textContent=e.message));else $('intakeFiles').textContent='Document Intake đang bị khóa.';await Promise.all(tasks)}

async function search(){const q=$('searchQuery')?.value.trim();if(!q)return;const r=await json('/api/search',{method:'POST',body:JSON.stringify({query:q})});$('searchResults').innerHTML=r.hits.length?r.hits.map(x=>`<div class="result"><strong>${esc(x.path)}</strong><div>${esc(x.kind)}</div><div class="detail">${esc(x.excerpt||'')}</div></div>`).join(''):'Không có kết quả.'}
async function loadRuns(){try{const r=await json('/api/terminal/running');$('runningList').innerHTML=r.runs.length?r.runs.map(x=>`<div class="result"><strong>${esc(x.runId)}</strong><div class="path">PID ${x.pid} · ${esc(x.startedAt)}</div></div>`).join(''):'Không có tiến trình MCP đang chạy.'}catch(e){$('runningList').textContent=e.message}}
function activityDetail(d){if(d==null||d==='')return '';let o=d;if(typeof d==='string'){try{o=JSON.parse(d)}catch{return esc(d.length>160?d.slice(0,160)+'…':d)}}if(typeof o!=='object')return esc(String(o));const parts=Object.entries(o).filter(([,v])=>v!=null&&typeof v!=='object').slice(0,4).map(([k,v])=>`${k}: ${String(v).slice(0,60)}`);const raw=JSON.stringify(o,null,2);return `${esc(parts.join(' · ')||'Chi tiết')}<details><summary>Xem dữ liệu gốc</summary><pre>${esc(raw.length>4000?raw.slice(0,4000)+'…':raw)}</pre></details>`}
async function loadActivity(){try{const r=await json('/api/activity');$('activityBody').innerHTML=(r.events||[]).map(x=>`<tr><td>${esc(new Date(x.at).toLocaleString('vi-VN'))}</td><td>${esc(x.action)}</td><td>${esc(x.status)}</td><td class="detail">${activityDetail(x.detail)}</td></tr>`).join('')}catch(e){toast(e.message)}}
async function loadSkills(){try{const r=await json('/api/skills');const q=$('skillSearch').value.trim().toLowerCase();const category=$('skillCategory').value;const rows=r.skills.filter(s=>(!q||`${s.id} ${s.name} ${s.description}`.toLowerCase().includes(q))&&(!category||s.category===category));setText('skillSummary',`${r.validation.enabled}/${r.validation.total} skill đang bật · ${r.validation.valid} hợp lệ`);$('skillList').innerHTML=rows.map(s=>`<div class="result"><div class="panel-heading"><div><strong>${esc(s.name)}</strong><div class="path">${esc(s.id)} · ${esc(s.category)} · ${s.resourceCount} tài nguyên</div></div><label><input class="skill-toggle" data-skill="${esc(s.id)}" type="checkbox" ${s.enabled?'checked':''}> Bật</label></div><div class="detail">${esc(s.description)}</div></div>`).join('')||'Không có skill phù hợp.';document.querySelectorAll('.skill-toggle').forEach(input=>input.onchange=async()=>{await json(`/api/skills/${encodeURIComponent(input.dataset.skill)}`,{method:'PATCH',body:JSON.stringify({enabled:input.checked})});toast('Đã cập nhật skill');loadSkills();load()})}catch(e){setText('skillSummary',e.message)}}
function toolStatus(tool){const label=tool.status==='partial'?'Một phần':tool.enabled?'Bật':'Tắt';return `<span class="tool-status ${tool.enabled?'tool-on':'tool-off'}">${label}</span>`}
async function loadTools(){try{const r=await json('/api/tools');toolsState=r;const q=$('toolSearch').value.trim().toLowerCase();const group=$('toolGroup').value;const rows=r.tools.filter(t=>(!q||`${t.name} ${t.group} ${t.description}`.toLowerCase().includes(q))&&(!group||t.group===group));$('toolMetrics').innerHTML=[metric(r.total,'Đã đăng ký'),metric(r.enabled,'Đang bật'),metric(r.disabled,'Đang tắt'),metric(r.partial,'Một phần')].join('');setText('toolSummary',`${rows.length}/${r.total} tool đang hiển thị · nguồn: MCP registry runtime`);$('toolBody').innerHTML=rows.map(t=>`<tr><td><strong>${esc(t.name)}</strong>${t.destructive?'<div class="path">destructive</div>':''}</td><td>${esc(t.group)}</td><td>${esc(t.permission)}</td><td>${toolStatus(t)}${t.reason?`<div class="detail">${esc(t.reason)}</div>`:''}</td><td>${esc(t.description)}</td></tr>`).join('')||'<tr><td colspan="5">Không có tool phù hợp.</td></tr>';renderSystemHealth()}catch(e){setText('toolSummary',e.message)}}

if($('refreshButton'))$('refreshButton').onclick=()=>load().then(()=>toast('Đã làm mới trạng thái'));
if($('quickHealth'))$('quickHealth').onclick=()=>load({forceDeep:true}).then(()=>toast(healthMeta.status==='healthy'?'MCP deep health check hoàn tất':'MCP đang degraded; tiếp tục dùng last-known-good'));
if($('startTunnel'))$('startTunnel').onclick=async()=>{await json('/api/tunnel/start',{method:'POST',body:'{}'});toast('Đang khởi động tunnel');setTimeout(load,1800)};
if($('stopTunnel'))$('stopTunnel').onclick=async()=>{await json('/api/tunnel/stop',{method:'POST',body:'{}'});load()};
if($('copyUrl'))$('copyUrl').onclick=()=>navigator.clipboard.writeText($('mcpUrl').value).then(()=>toast('Đã sao chép URL MCP remote'));if($('copyLocalUrl'))$('copyLocalUrl').onclick=()=>navigator.clipboard.writeText($('localMcpUrl').value).then(()=>toast('Đã sao chép URL MCP local'));
if($('savePermissions'))$('savePermissions').onclick=async()=>{await json('/api/config',{method:'PATCH',body:JSON.stringify({writeEnabled:$('writeEnabled').checked,terminalEnabled:$('terminalEnabled').checked,skillsEnabled:$('skillsEnabled').checked,screenEnabled:$('screenEnabled').checked,desktopEnabled:$('desktopEnabled').checked,visualDesktopEnabled:$('visualDesktopEnabled').checked,intakeEnabled:$('intakeEnabled').checked,ocrEnabled:$('ocrEnabled').checked,intakeRoots:$('intakeRoots').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean)})});toast('Đã lưu quyền');load()};
if($('emergencyButton'))$('emergencyButton').onclick=async()=>{const enabled=!state.emergencyStop;await json('/api/emergency',{method:'POST',body:JSON.stringify({enabled})});toast(enabled?'Đã dừng khẩn cấp':'Đã mở khóa hệ thống');load()};
if($('runIndex'))$('runIndex').onclick=async()=>{if(!confirm(`Lập chỉ mục ${state.root?.[0]||'root đã cấu hình'} có thể mất nhiều thời gian. Tiếp tục?`))return;setText('indexStatus','Đang lập chỉ mục...');try{const r=await json('/api/index',{method:'POST',body:JSON.stringify({root:state.root?.[0],maxFiles:20000})});setText('indexStatus',`Đã quét ${r.scanned}, index ${r.indexed}, bỏ qua ${r.skipped}.`);load()}catch(e){setText('indexStatus',e.message)}};
if($('searchButton'))$('searchButton').onclick=search;if($('searchQuery'))$('searchQuery').onkeydown=e=>{if(e.key==='Enter')search()};if($('refreshRuns'))$('refreshRuns').onclick=loadRuns;if($('refreshActivity'))$('refreshActivity').onclick=loadActivity;if($('refreshScreens'))$('refreshScreens').onclick=loadScreens;if($('refreshSkills'))$('refreshSkills').onclick=loadSkills;if($('searchSkills'))$('searchSkills').onclick=loadSkills;if($('skillSearch'))$('skillSearch').onkeydown=e=>{if(e.key==='Enter')loadSkills()};if($('skillCategory'))$('skillCategory').onchange=loadSkills;if($('refreshTools'))$('refreshTools').onclick=loadTools;if($('searchTools'))$('searchTools').onclick=loadTools;if($('toolSearch'))$('toolSearch').onkeydown=e=>{if(e.key==='Enter')loadTools()};if($('toolGroup'))$('toolGroup').onchange=loadTools;
if($('rotateCode'))$('rotateCode').onclick=async()=>{if(!confirm('Thu hồi toàn bộ OAuth token và tạo pairing code mới?'))return;const r=await json('/api/oauth/rotate',{method:'POST',body:'{}'});$('pairingCode').value=r.pairingCode;toast('Đã xoay mã và thu hồi phiên')};
const cmd=$('commandInput');if(cmd){document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();cmd.focus();cmd.select()}});cmd.addEventListener('keydown',e=>{if(e.key!=='Enter')return;const q=cmd.value.trim().toLowerCase();const map=[['health','chat-health'],['chat','chat-health'],['memory','memory'],['project','projects'],['file','workspace'],['office','workspace'],['screen','desktop'],['desktop','desktop'],['terminal','automation'],['tool','skills'],['skill','skills'],['security','security'],['setting','settings'],['activity','activity'],['connection','connections']];const hit=map.find(([k])=>q.includes(k));if(hit){gotoTab(hit[1]);cmd.value=''}else{toast('Gợi ý: health, memory, project, files, terminal, tools, security...')}})}
load();
const refreshInterval=setInterval(()=>{if(!document.hidden)load()},15000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)load()});
window.addEventListener('online',()=>load());
window.addEventListener('beforeunload',()=>clearInterval(refreshInterval));

